202	// ── Supabase Database generic type ────────────────────────────
203	
204	export interface Database {
205	  public: {
206	    Tables: {
207	      profiles: {
208	        Row: ProfileRow;
209	        Insert: ProfileInsert;
210	        Update: ProfileUpdate;
211	      };
212	      scans: {
213	        Row: ScanRow;
214	        Insert: ScanInsert;
215	        Update: ScanUpdate;
216	      };
217	      scan_results: {
218	        Row: ScanResultRow;
219	        Insert: ScanResultInsert;
220	        Update: ScanResultUpdate;
221	      };
222	      integrations: {
223	        Row: IntegrationRow;
224	        Insert: IntegrationInsert;
225	        Update: IntegrationUpdate;
226	      };
227	      copy_rewrites: {
228	        Row: CopyRewriteRow;
229	        Insert: CopyRewriteInsert;
230	        Update: CopyRewriteUpdate;
231	      };
232	      audit_logs: {
233	        Row: AuditLogRow;
234	        Insert: AuditLogInsert;
235	        Update: Partial<Omit<AuditLogRow, "id" | "created_at">>;
236	      };
237	      scan_history: {
238	        Row: ScanHistoryInsert & { id: string };
239	        Insert: ScanHistoryInsert;
240	        Update: Partial<ScanHistoryInsert>;
241	      };
242	      competitor_groups: {
243	        Row: CompetitorGroupRow;
244	        Insert: CompetitorGroupInsert;
245	        Update: Partial<Omit<CompetitorGroupRow, "id" | "user_id" | "created_at">>;
246	      };
247	      competitor_urls: {
248	        Row: CompetitorUrlRow;
249	        Insert: CompetitorUrlInsert;
250	        Update: CompetitorUrlUpdate;
251	      };
252	      industry_benchmarks: {
253	        Row: IndustryBenchmarkRow;
254	        Insert: Omit<IndustryBenchmarkRow, "id" | "updated_at">;
255	        Update: Partial<Omit<IndustryBenchmarkRow, "id">>;
256	      };
257	    };
258	    Views: Record<string, never>;
259	    Functions: {
260	      increment_scan_usage: {
261	        Args: { user_uuid: string };
262	        Returns: boolean;
263	      };
264	      reset_monthly_scans: {
265	        Args: Record<string, never>;
266	        Returns: void;
267	      };
268	      is_admin: {
269	        Args: Record<string, never>;
270	        Returns: boolean;
271	      };
272	    };
273	    Enums: Record<string, never>;
274	  };
275	}
