268	// ── Request types ─────────────────────────────────────────────────
269	
270	type EmailRequest =
271	  | { type: "welcome"; to: string; data: WelcomeData }
272	  | { type: "scan_complete"; to: string; data: ScanCompleteData }
273	  | { type: "weekly_digest"; to: string; data: WeeklyDigestData };
274	
275	// ── Resend call ───────────────────────────────────────────────────
276	
277	async function sendViaResend(
278	  to: string,
279	  subject: string,
280	  html: string,
281	): Promise<void> {
282	  const apiKey = Deno.env.get("RESEND_API_KEY");
283	  if (!apiKey) {
284	    throw new Error("RESEND_API_KEY env var is not set");
285	  }
286	
287	  const res = await fetch("https://api.resend.com/emails", {
288	    method: "POST",
289	    headers: {
290	      "Authorization": `Bearer ${apiKey}`,
291	      "Content-Type": "application/json",
292	    },
293	    body: JSON.stringify({
294	      from: FROM_ADDRESS,
295	      to,
296	      subject,
297	      html,
298	    }),
299	  });
300	
301	  if (!res.ok) {
302	    const body = await res.text();
303	    throw new Error(`Resend API error ${res.status}: ${body.slice(0, 300)}`);
304	  }
305	}
306	
307	// ── Main handler ──────────────────────────────────────────────────
308	
309	serve(async (req: Request) => {
310	  if (req.method === "OPTIONS") {
311	    return new Response("ok", { headers: corsHeaders });
312	  }
313	
314	  if (req.method !== "POST") {
315	    return jsonResponse({ error: "Method not allowed" }, 405);
316	  }
317	
318	  const appUrl = Deno.env.get("APP_URL") ?? Deno.env.get("SITE_URL") ?? "https://app.convertscan.com";
319	
320	  let payload: EmailRequest;
321	  try {
322	    payload = await req.json() as EmailRequest;
323	  } catch {
324	    return jsonResponse({ error: "Invalid JSON body" }, 400);
325	  }
326	
327	  if (!payload.type || !payload.to) {
328	    return jsonResponse({ error: "type and to are required" }, 400);
329	  }
330	
331	  let subject: string;
332	  let html: string;
333	
334	  try {
335	    switch (payload.type) {
336	      case "welcome": {
337	        const result = buildWelcomeEmail(payload.to, payload.data, appUrl);
338	        subject = result.subject;
339	        html = result.html;
340	        break;
341	      }
342	      case "scan_complete": {
343	        const result = buildScanCompleteEmail(payload.to, payload.data, appUrl);
344	        subject = result.subject;
345	        html = result.html;
346	        break;
347	      }
348	      case "weekly_digest": {
349	        const result = buildWeeklyDigestEmail(payload.to, payload.data, appUrl);
350	        subject = result.subject;
351	        html = result.html;
352	        break;
353	      }
354	      default: {
355	        return jsonResponse({ error: `Unknown email type: ${(payload as { type: string }).type}` }, 400);
356	      }
357	    }
358	  } catch (err) {
359	    console.error("Email template build failed:", err);
360	    return jsonResponse({ error: "Failed to build email template" }, 500);
361	  }
362	
363	  try {
364	    await sendViaResend(payload.to, subject, html);
365	    return jsonResponse({ status: "sent", type: payload.type, to: payload.to });
366	  } catch (err) {
367	    console.error("Resend delivery failed:", err);
368	    return jsonResponse(
369	      { error: "Email delivery failed", detail: err instanceof Error ? err.message : "unknown" },
370	      500,
371	    );
372	  }
373	});
