import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { Team, TeamMember, TeamInvite } from "@/types/index";
import type { TeamRow, TeamMemberRow, TeamInviteRow } from "@/types/database";

// ── Query keys ──────────────────────────────────────────────────

export const teamKeys = {
  all: ["teams"] as const,
  lists: () => [...teamKeys.all, "list"] as const,
  list: (userId: string) => [...teamKeys.lists(), userId] as const,
  details: () => [...teamKeys.all, "detail"] as const,
  detail: (id: string) => [...teamKeys.details(), id] as const,
  members: (teamId: string) => [...teamKeys.all, "members", teamId] as const,
  invites: (teamId: string) => [...teamKeys.all, "invites", teamId] as const,
};

// ── Row → App type mappers ───────────────────────────────────────

function rowToTeam(row: TeamRow): Team {
  return {
    id: row.id,
    name: row.name,
    owner_id: row.owner_id,
    logo_url: row.logo_url,
    brand_color: row.brand_color,
    custom_domain: row.custom_domain,
    created_at: row.created_at,
  };
}

interface TeamMemberRowWithProfile extends TeamMemberRow {
  profiles?: {
    full_name: string;
    email: string;
    avatar_url: string | null;
  } | null;
}

function rowToTeamMember(row: TeamMemberRowWithProfile): TeamMember {
  return {
    id: row.id,
    team_id: row.team_id,
    user_id: row.user_id,
    role: row.role,
    joined_at: row.joined_at,
    profile: row.profiles
      ? {
          full_name: row.profiles.full_name,
          email: row.profiles.email,
          avatar_url: row.profiles.avatar_url,
        }
      : undefined,
  };
}

function rowToTeamInvite(row: TeamInviteRow): TeamInvite {
  return {
    id: row.id,
    team_id: row.team_id,
    email: row.email,
    role: row.role,
    token: row.token,
    expires_at: row.expires_at,
    created_at: row.created_at,
  };
}

// ── useTeams ─────────────────────────────────────────────────────
// Returns all teams where the current user is a member.

export function useTeams() {
  const { user } = useAuth();

  return useQuery({
    queryKey: teamKeys.list(user?.id ?? ""),
    queryFn: async (): Promise<Team[]> => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("team_members")
        .select("team_id, teams(*)")
        .eq("user_id", user.id)
        .order("joined_at", { ascending: true });

      if (error) throw new Error(error.message);

      return (data ?? [])
        .map((row) => {
          const team = (row as { team_id: string; teams: TeamRow | null }).teams;
          return team ? rowToTeam(team) : null;
        })
        .filter((t): t is Team => t !== null);
    },
    enabled: !!user?.id,
  });
}

// ── useTeam ──────────────────────────────────────────────────────

export function useTeam(teamId: string | undefined) {
  return useQuery({
    queryKey: teamKeys.detail(teamId ?? ""),
    queryFn: async (): Promise<Team | null> => {
      if (!teamId) return null;

      const { data, error } = await supabase
        .from("teams")
        .select("*")
        .eq("id", teamId)
        .single();

      if (error) {
        if (error.code === "PGRST116") return null;
        throw new Error(error.message);
      }

      return rowToTeam(data as TeamRow);
    },
    enabled: !!teamId,
  });
}

// ── useTeamMembers ───────────────────────────────────────────────

export function useTeamMembers(teamId: string | undefined) {
  return useQuery({
    queryKey: teamKeys.members(teamId ?? ""),
    queryFn: async (): Promise<TeamMember[]> => {
      if (!teamId) return [];

      const { data, error } = await supabase
        .from("team_members")
        .select("*, profiles(full_name, email, avatar_url)")
        .eq("team_id", teamId)
        .order("joined_at", { ascending: true });

      if (error) throw new Error(error.message);

      return (data as TeamMemberRowWithProfile[]).map(rowToTeamMember);
    },
    enabled: !!teamId,
  });
}

// ── useTeamInvites ───────────────────────────────────────────────

export function useTeamInvites(teamId: string | undefined) {
  return useQuery({
    queryKey: teamKeys.invites(teamId ?? ""),
    queryFn: async (): Promise<TeamInvite[]> => {
      if (!teamId) return [];

      const { data, error } = await supabase
        .from("team_invites")
        .select("*")
        .eq("team_id", teamId)
        .gt("expires_at", new Date().toISOString())
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);

      return (data as TeamInviteRow[]).map(rowToTeamInvite);
    },
    enabled: !!teamId,
  });
}

// ── useCreateTeam ────────────────────────────────────────────────

export function useCreateTeam() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (name: string): Promise<Team> => {
      if (!user?.id) throw new Error("Not authenticated");

      // Create team
      const { data: teamData, error: teamError } = await supabase
        .from("teams")
        .insert({ name, owner_id: user.id })
        .select("*")
        .single();

      if (teamError) throw new Error(teamError.message);

      const team = rowToTeam(teamData as TeamRow);

      // Insert owner as team_member
      const { error: memberError } = await supabase
        .from("team_members")
        .insert({ team_id: team.id, user_id: user.id, role: "owner" });

      if (memberError) throw new Error(memberError.message);

      return team;
    },
    onSuccess: (data) => {
      if (!user?.id) return;
      queryClient.setQueryData<Team[]>(teamKeys.list(user.id), (prev) =>
        prev ? [...prev, data] : [data]
      );
      queryClient.setQueryData(teamKeys.detail(data.id), data);
      toast.success(`Team "${data.name}" created`);
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });
}

// ── useUpdateTeam ────────────────────────────────────────────────

export function useUpdateTeam(teamId: string) {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (updates: {
      name?: string;
      logo_url?: string | null;
      brand_color?: string;
      custom_domain?: string | null;
    }): Promise<Team> => {
      const { data, error } = await supabase
        .from("teams")
        .update(updates)
        .eq("id", teamId)
        .select("*")
        .single();

      if (error) throw new Error(error.message);
      return rowToTeam(data as TeamRow);
    },
    onSuccess: (data) => {
      queryClient.setQueryData(teamKeys.detail(teamId), data);
      if (user?.id) {
        queryClient.setQueryData<Team[]>(teamKeys.list(user.id), (prev) =>
          prev ? prev.map((t) => (t.id === teamId ? data : t)) : [data]
        );
      }
      toast.success("Team updated");
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });
}

// ── useDeleteTeam ────────────────────────────────────────────────

export function useDeleteTeam() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (teamId: string): Promise<void> => {
      const { error } = await supabase.from("teams").delete().eq("id", teamId);
      if (error) throw new Error(error.message);
    },
    onSuccess: (_data, teamId) => {
      if (!user?.id) return;
      queryClient.setQueryData<Team[]>(teamKeys.list(user.id), (prev) =>
        prev ? prev.filter((t) => t.id !== teamId) : []
      );
      queryClient.removeQueries({ queryKey: teamKeys.detail(teamId) });
      toast.success("Team deleted");
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });
}

// ── useInviteMember ──────────────────────────────────────────────

export function useInviteMember() {
  const { profile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      teamId,
      email,
      role,
    }: {
      teamId: string;
      email: string;
      role: string;
    }): Promise<void> => {
      const { error } = await supabase.functions.invoke("team-invite", {
        body: {
          team_id: teamId,
          email,
          role,
          inviter_name: profile?.full_name ?? "A team member",
        },
      });

      if (error) throw new Error(error.message);
    },
    onSuccess: (_data, { teamId }) => {
      queryClient.invalidateQueries({ queryKey: teamKeys.invites(teamId) });
      toast.success("Invitation sent");
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });
}

// ── useRevokeInvite ──────────────────────────────────────────────

export function useRevokeInvite(teamId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (inviteId: string): Promise<void> => {
      const { error } = await supabase
        .from("team_invites")
        .delete()
        .eq("id", inviteId);
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: teamKeys.invites(teamId) });
      toast.success("Invite revoked");
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });
}

// ── useRemoveMember ──────────────────────────────────────────────

export function useRemoveMember(teamId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (memberId: string): Promise<void> => {
      const { error } = await supabase
        .from("team_members")
        .delete()
        .eq("id", memberId);
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: teamKeys.members(teamId) });
      toast.success("Member removed");
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });
}

// ── useUpdateMemberRole ──────────────────────────────────────────

export function useUpdateMemberRole(teamId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      memberId,
      role,
    }: {
      memberId: string;
      role: "admin" | "member";
    }): Promise<void> => {
      const { error } = await supabase
        .from("team_members")
        .update({ role })
        .eq("id", memberId);
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: teamKeys.members(teamId) });
      toast.success("Role updated");
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });
}

// ── useAcceptInvite ──────────────────────────────────────────────

export function useAcceptInvite() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (token: string): Promise<{ team_id: string }> => {
      if (!user?.id) throw new Error("You must be logged in to accept an invitation");

      // Fetch and validate invite
      const { data: invite, error: fetchError } = await supabase
        .from("team_invites")
        .select("*")
        .eq("token", token)
        .gt("expires_at", new Date().toISOString())
        .single();

      if (fetchError || !invite) {
        throw new Error("Invitation not found or has expired");
      }

      const typedInvite = invite as TeamInviteRow;

      // Check not already a member
      const { data: existing } = await supabase
        .from("team_members")
        .select("id")
        .eq("team_id", typedInvite.team_id)
        .eq("user_id", user.id)
        .maybeSingle();

      if (existing) {
        // Already a member — just delete invite and return
        await supabase.from("team_invites").delete().eq("id", typedInvite.id);
        return { team_id: typedInvite.team_id };
      }

      // Create team_member row
      const { error: insertError } = await supabase
        .from("team_members")
        .insert({
          team_id: typedInvite.team_id,
          user_id: user.id,
          role: typedInvite.role as "admin" | "member",
        });

      if (insertError) throw new Error(insertError.message);

      // Delete invite
      await supabase.from("team_invites").delete().eq("id", typedInvite.id);

      return { team_id: typedInvite.team_id };
    },
    onSuccess: (_data, _token) => {
      if (user?.id) {
        queryClient.invalidateQueries({ queryKey: teamKeys.list(user.id) });
      }
      toast.success("You have joined the team");
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });
}

