/**
 * team-invite — Edge Function
 *
 * Creates a team invite record and sends an invitation email.
 *
 * Request body: { team_id: string; email: string; role: string; inviter_name: string }
 *
 * Required env vars:
 *   SUPABASE_URL
 *   SUPABASE_SERVICE_ROLE_KEY
 *   APP_URL / SITE_URL
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ── CORS ──────────────────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

// ── Handler ───────────────────────────────────────────────────────

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed" }, 405);
  }

  // Verify JWT from caller
  const authHeader = req.headers.get("Authorization");
  if (!authHeader) {
    return jsonResponse({ error: "Missing Authorization header" }, 401);
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

  if (!supabaseUrl || !serviceRoleKey) {
    return jsonResponse({ error: "Server misconfiguration" }, 500);
  }

  // Use service role client so we can insert invites + read team name
  const adminClient = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false },
  });

  // Parse and validate body
  let body: {
    team_id: string;
    email: string;
    role: string;
    inviter_name: string;
  };

  try {
    body = await req.json();
  } catch {
    return jsonResponse({ error: "Invalid JSON body" }, 400);
  }

  const { team_id, email, role, inviter_name } = body;

  if (!team_id || !email || !role) {
    return jsonResponse({ error: "team_id, email, and role are required" }, 400);
  }

  // Fetch team name
  const { data: team, error: teamError } = await adminClient
    .from("teams")
    .select("name")
    .eq("id", team_id)
    .single();

  if (teamError || !team) {
    return jsonResponse({ error: "Team not found" }, 404);
  }

  const teamName = (team as { name: string }).name;

  // Check if a pending invite already exists for this email+team
  const { data: existing } = await adminClient
    .from("team_invites")
    .select("id")
    .eq("team_id", team_id)
    .eq("email", email)
    .maybeSingle();

  if (existing) {
    return jsonResponse({ error: "An invitation for this email is already pending" }, 409);
  }

  // Generate secure token and create invite row
  const token = crypto.randomUUID();
  const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

  const { error: insertError } = await adminClient.from("team_invites").insert({
    team_id,
    email,
    role,
    token,
    expires_at: expiresAt,
  });

  if (insertError) {
    return jsonResponse({ error: insertError.message }, 500);
  }

  // Build accept link
  const appUrl =
    Deno.env.get("APP_URL") ??
    Deno.env.get("SITE_URL") ??
    "https://app.convertscan.com";

  const acceptLink = `${appUrl}/invite/${token}`;

  // Send invitation email via send-email function
  const emailPayload = {
    type: "team_invite",
    to: email,
    data: {
      inviter_name,
      team_name: teamName,
      accept_link: acceptLink,
      role,
      expires_at: expiresAt,
    },
  };

  // Invoke send-email — use service role so it bypasses auth on the function
  const { error: emailError } = await adminClient.functions.invoke("send-email", {
    body: emailPayload,
  });

  if (emailError) {
    // Invite row is already created — don't fail entirely, just warn
    console.error("Failed to send invite email:", emailError.message);
    return jsonResponse({
      status: "invite_created_email_failed",
      token,
      detail: emailError.message,
    });
  }

  return jsonResponse({ status: "invited", token });
});

