import { useTeams } from "@/hooks/use-teams";
import { CreateTeamDialog } from "@/components/team/CreateTeamDialog";
import { cn } from "@/lib/utils";

export function TeamSwitcher() {
  const { activeTeamId, switchTeam } = useAuth();
  const { data: teams } = useTeams();
  const [createOpen, setCreateOpen] = useState(false);

  const activeTeam = teams?.find((t) => t.id === activeTeamId) ?? null;
  const label = activeTeam?.name ?? "Personal";

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            variant="ghost"
            size="sm"
            className="w-full justify-between px-2 h-9 text-white/70 hover:text-white hover:bg-white/5 font-normal"
          >
            <span className="flex items-center gap-2 truncate">
              <Users className="h-3.5 w-3.5 shrink-0" />
              <span className="truncate text-xs">{label}</span>
            </span>
            <ChevronDown className="h-3 w-3 shrink-0 ml-1 opacity-50" />
          </Button>
        </DropdownMenuTrigger>

        <DropdownMenuContent
          align="start"
          sideOffset={4}
          className="w-52"
        >
          <DropdownMenuLabel className="text-xs text-muted-foreground font-normal pb-1">
            Workspaces
          </DropdownMenuLabel>

          {/* Personal workspace */}
          <DropdownMenuItem
            onClick={() => switchTeam(null)}
            className="cursor-pointer"
          >
            <span className="flex items-center gap-2 flex-1">
              <span className="flex h-5 w-5 items-center justify-center rounded bg-muted text-xs font-semibold">
                P
              </span>
              <span className="text-sm">Personal</span>
            </span>
            {!activeTeamId && <Check className="h-3.5 w-3.5 text-primary" />}
          </DropdownMenuItem>

          {/* Team workspaces */}
          {teams && teams.length > 0 && (
            <>
              <DropdownMenuSeparator />
              {teams.map((team) => (
                <DropdownMenuItem
                  key={team.id}
                  onClick={() => switchTeam(team.id)}
                  className="cursor-pointer"
                >
                  <span className="flex items-center gap-2 flex-1 min-w-0">
                    <span
                      className={cn(
                        "flex h-5 w-5 shrink-0 items-center justify-center rounded text-xs font-semibold text-white"
                      )}
                      style={{ backgroundColor: team.brand_color ?? "#5B5FC7" }}
                    >
                      {team.name.charAt(0).toUpperCase()}
                    </span>
                    <span className="truncate text-sm">{team.name}</span>
                  </span>
                  {activeTeamId === team.id && (
                    <Check className="h-3.5 w-3.5 text-primary shrink-0" />
                  )}
                </DropdownMenuItem>
              ))}
            </>
          )}

          <DropdownMenuSeparator />
          <DropdownMenuItem
            onClick={() => setCreateOpen(true)}
            className="cursor-pointer text-primary"
          >
            <Plus className="h-3.5 w-3.5 mr-2" />
            <span className="text-sm">Create Team</span>
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>

      <CreateTeamDialog open={createOpen} onOpenChange={setCreateOpen} />
    </>
  );
}

import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Loader2 } from "lucide-react";
import { useCreateTeam } from "@/hooks/use-teams";
import { useAuth } from "@/contexts/AuthContext";
import { useNavigate } from "react-router-dom";

interface CreateTeamDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function CreateTeamDialog({ open, onOpenChange }: CreateTeamDialogProps) {
  const [name, setName] = useState("");
  const createTeam = useCreateTeam();
  const { switchTeam } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    const team = await createTeam.mutateAsync(name.trim());
    switchTeam(team.id);
    setName("");
    onOpenChange(false);
    navigate(`/team/${team.id}`);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-sm">
        <DialogHeader>
          <DialogTitle>Create a team workspace</DialogTitle>
          <DialogDescription>
            Collaborate with teammates on shared scans and reports.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-1.5">
            <Label htmlFor="team-name">Team name</Label>
            <Input
              id="team-name"
              placeholder="e.g. Acme Marketing"
              value={name}
              onChange={(e) => setName(e.target.value)}
              autoFocus
              maxLength={80}
            />
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={!name.trim() || createTeam.isPending}
            >
              {createTeam.isPending && (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              )}
              Create Team
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

