export function MemberList({ teamId, members, ownerId }: MemberListProps) {
  const { user } = useAuth();
  const removeMember = useRemoveMember(teamId);
  const updateRole = useUpdateMemberRole(teamId);

  const isOwner = user?.id === ownerId;

  return (
    <Table>
      <TableHeader>
        <TableRow className="hover:bg-transparent">
          <TableHead className="w-[200px]">Member</TableHead>
          <TableHead className="hidden sm:table-cell">Email</TableHead>
          <TableHead>Role</TableHead>
          <TableHead className="hidden md:table-cell">Joined</TableHead>
          {isOwner && <TableHead className="w-10" />}
        </TableRow>
      </TableHeader>
      <TableBody>
        {members.map((member) => {
          const badgeCfg = ROLE_BADGE[member.role];
          const isMemberOwner = member.role === "owner";
          const isCurrentUser = member.user_id === user?.id;

          return (
            <TableRow key={member.id}>
              <TableCell>
                <div className="flex items-center gap-2.5">
                  <MemberAvatar
                    name={member.profile?.full_name ?? "?"}
                    avatarUrl={member.profile?.avatar_url ?? null}
                  />
                  <span className="text-sm font-medium text-foreground truncate max-w-[140px]">
                    {member.profile?.full_name ?? "Unknown"}
                    {isCurrentUser && (
                      <span className="ml-1 text-xs text-muted-foreground">(you)</span>
                    )}
                  </span>
                </div>
              </TableCell>
              <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                {member.profile?.email ?? "—"}
              </TableCell>
              <TableCell>
                <Badge
                  variant="outline"
                  className={cn("text-xs font-medium capitalize", badgeCfg.className)}
                >
                  {badgeCfg.label}
                </Badge>
              </TableCell>
              <TableCell className="hidden md:table-cell text-sm text-muted-foreground">
                {formatRelativeDate(member.joined_at)}
              </TableCell>
              {isOwner && (
                <TableCell>
                  {!isMemberOwner && (
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7 text-muted-foreground hover:text-foreground"
                        >
                          <MoreHorizontal className="h-4 w-4" />
                          <span className="sr-only">Member actions</span>
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        {member.role === "member" && (
                          <DropdownMenuItem
                            onClick={() =>
                              updateRole.mutate({ memberId: member.id, role: "admin" })
                            }
                            disabled={updateRole.isPending}
                          >
                            <Shield className="h-3.5 w-3.5 mr-2 text-blue-500" />
                            Promote to Admin
                          </DropdownMenuItem>
                        )}
                        {member.role === "admin" && (
                          <DropdownMenuItem
                            onClick={() =>
                              updateRole.mutate({ memberId: member.id, role: "member" })
                            }
                            disabled={updateRole.isPending}
                          >
                            <Shield className="h-3.5 w-3.5 mr-2 text-muted-foreground" />
                            Demote to Member
                          </DropdownMenuItem>
                        )}
                        <DropdownMenuSeparator />
                        <DropdownMenuItem
                          onClick={() => removeMember.mutate(member.id)}
                          disabled={removeMember.isPending}
                          className="text-destructive focus:text-destructive"
                        >
                          <UserMinus className="h-3.5 w-3.5 mr-2" />
                          Remove from team
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  )}
                </TableCell>
              )}
            </TableRow>
          );
        })}
      </TableBody>
    </Table>
  );
}

import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Loader2, Mail, Trash2, UserPlus } from "lucide-react";
import { useInviteMember, useRevokeInvite, useTeamInvites } from "@/hooks/use-teams";
import { Separator } from "@/components/ui/separator";
import { formatRelativeDate } from "@/lib/score-utils";

interface InviteMemberDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  teamId: string;
}

export function InviteMemberDialog({
  open,
  onOpenChange,
  teamId,
}: InviteMemberDialogProps) {
  const [email, setEmail] = useState("");
  const [role, setRole] = useState<"admin" | "member">("member");

  const inviteMember = useInviteMember();
  const revokeInvite = useRevokeInvite(teamId);
  const { data: pendingInvites } = useTeamInvites(teamId);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.trim()) return;

    await inviteMember.mutateAsync({ teamId, email: email.trim(), role });
    setEmail("");
    setRole("member");
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Invite team member</DialogTitle>
          <DialogDescription>
            Send an email invitation to collaborate on this workspace.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="flex gap-2">
            <div className="flex-1 space-y-1.5">
              <Label htmlFor="invite-email">Email address</Label>
              <Input
                id="invite-email"
                type="email"
                placeholder="colleague@company.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                autoFocus
              />
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="invite-role">Role</Label>
              <Select
                value={role}
                onValueChange={(v) => setRole(v as "admin" | "member")}
              >
                <SelectTrigger id="invite-role" className="w-28">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="admin">Admin</SelectItem>
                  <SelectItem value="member">Member</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <Button
            type="submit"
            className="w-full"
            disabled={!email.trim() || inviteMember.isPending}
          >
            {inviteMember.isPending ? (
              <Loader2 className="h-4 w-4 mr-2 animate-spin" />
            ) : (
              <UserPlus className="h-4 w-4 mr-2" />
            )}
            Send Invitation
          </Button>
        </form>

        {/* Pending invites */}
        {pendingInvites && pendingInvites.length > 0 && (
          <>
            <Separator />
            <div className="space-y-2">
              <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                Pending invitations ({pendingInvites.length})
              </p>
              <ul className="space-y-1.5">
                {pendingInvites.map((invite) => (
                  <li
                    key={invite.id}
                    className="flex items-center justify-between rounded-lg border border-border/40 px-3 py-2 bg-muted/20"
                  >
                    <div className="flex items-center gap-2 min-w-0">
                      <Mail className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
                      <span className="text-sm truncate">{invite.email}</span>
                      <Badge
                        variant="outline"
                        className="text-xs capitalize hidden sm:inline-flex"
                      >
                        {invite.role}
                      </Badge>
                    </div>
                    <div className="flex items-center gap-2 shrink-0 ml-2">
                      <span className="text-xs text-muted-foreground hidden sm:block">
                        Expires {formatRelativeDate(invite.expires_at)}
                      </span>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-6 w-6 text-muted-foreground hover:text-destructive"
                        onClick={() => revokeInvite.mutate(invite.id)}
                        disabled={revokeInvite.isPending}
                        title="Revoke invite"
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </Button>
                    </div>
                  </li>
                ))}
              </ul>
            </div>
          </>
        )}

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Close
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

