import { useMemo } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import {
  Globe,
  Settings,
  ScanLine,
  Target,
  Users,
  AlertTriangle,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { PageTransition } from "@/components/shared/PageTransition";
import { EmptyState } from "@/components/shared/EmptyState";
import { ErrorState } from "@/components/shared/ErrorState";
import { PremiumLock } from "@/components/shared/PremiumLock";
import { KpiCard } from "@/components/shared/KpiCard";
import { useAuth } from "@/contexts/AuthContext";
import { useTeam, useTeamMembers } from "@/hooks/use-teams";
import { useTeamScans } from "@/hooks/use-scans";
import { getScoreColor, formatRelativeDate } from "@/lib/score-utils";
import { isProPlus } from "@/types/index";
import { cn } from "@/lib/utils";

// ── Status badge ─────────────────────────────────────────────────

function StatusBadge({ status }: { status: string }) {
  if (status === "completed")
    return (
      <Badge
        variant="outline"
        className="border-emerald-200/80 bg-emerald-50/50 text-emerald-700 text-xs"
      >
        Completed
      </Badge>
    );
  if (status === "analyzing")
    return (
      <Badge
        variant="outline"
        className="border-amber-200/80 bg-amber-50/50 text-amber-700 text-xs animate-pulse"
      >
        Analyzing
      </Badge>
    );
  if (status === "failed")
    return (
      <Badge
        variant="outline"
        className="border-red-200/80 bg-red-50/50 text-red-700 text-xs"
      >
        Failed
      </Badge>
    );
  return (
    <Badge variant="outline" className="text-xs">
      Pending
    </Badge>
  );
}

// ── Loading skeleton ──────────────────────────────────────────────

function DashboardSkeleton() {
  return (
    <div className="space-y-6 p-6">
      <div className="flex items-center justify-between">
        <div className="space-y-2">
          <Skeleton className="h-7 w-40" />
          <Skeleton className="h-4 w-24" />
        </div>
        <Skeleton className="h-9 w-24" />
      </div>
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        {Array.from({ length: 4 }).map((_, i) => (
          <Skeleton key={i} className="h-28" />
        ))}
      </div>
      <Skeleton className="h-64" />
    </div>
  );
}

// ── Member avatars strip ──────────────────────────────────────────

function MemberAvatarsStrip({
  members,
  teamId,
}: {
  members: { id: string; profile?: { full_name: string; avatar_url: string | null } }[];
  teamId: string;
}) {
  const visible = members.slice(0, 5);
  const overflow = members.length - 5;

  return (
    <div className="flex items-center gap-2">
      <div className="flex -space-x-2">
        {visible.map((m) =>
          m.profile?.avatar_url ? (
            <img
              key={m.id}
              src={m.profile.avatar_url}
              alt={m.profile.full_name}
              className="h-7 w-7 rounded-full border-2 border-background object-cover"
            />
          ) : (
            <div
              key={m.id}
              className="flex h-7 w-7 items-center justify-center rounded-full border-2 border-background bg-primary/10 text-primary text-xs font-semibold"
            >
              {(m.profile?.full_name ?? "?").charAt(0).toUpperCase()}
            </div>
          )
        )}
        {overflow > 0 && (
          <div className="flex h-7 w-7 items-center justify-center rounded-full border-2 border-background bg-muted text-xs font-medium text-muted-foreground">
            +{overflow}
          </div>
        )}
      </div>
      <Link
        to={`/team/${teamId}/settings`}
        className="text-xs text-muted-foreground hover:text-foreground transition-colors"
      >
        {members.length} {members.length === 1 ? "member" : "members"}
      </Link>
    </div>
  );
}

// ── Page ─────────────────────────────────────────────────────────

export default function TeamDashboard() {
  const { id: teamId } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { profile } = useAuth();

  const {
    data: team,
    isLoading: teamLoading,
    isError: teamError,
    refetch: refetchTeam,
  } = useTeam(teamId);

  const { data: members = [] } = useTeamMembers(teamId);
  const {
    data: scans = [],
    isLoading: scansLoading,
    isError: scansError,
    refetch: refetchScans,
  } = useTeamScans(teamId);

  // Plan gate
  const canAccess = profile ? isProPlus(profile.plan) : false;

  const stats = useMemo(() => {
    const completed = scans.filter((s) => s.status === "completed");
    const totalScans = scans.length;
    const avgScore =
      completed.length > 0
        ? Math.round(
            completed.reduce((acc, s) => acc + (s.overall_score ?? 0), 0) /
              completed.length
          )
        : 0;
    const memberCount = members.length;
    const criticalIssues = completed.reduce((acc, s) => acc + s.critical_issues, 0);
    return { totalScans, avgScore, memberCount, criticalIssues };
  }, [scans, members]);

  if (teamLoading) return <DashboardSkeleton />;

  if (teamError || !team) {
    return (
      <ErrorState
        title="Team not found"
        description="This team doesn't exist or you don't have access."
        onRetry={refetchTeam}
        className="p-12"
      />
    );
  }

  const content = (
    <PageTransition className="space-y-6 p-6">
      {/* Header */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="space-y-1">
          <h1 className="text-2xl font-bold tracking-tight">{team.name}</h1>
          <MemberAvatarsStrip members={members} teamId={team.id} />
        </div>
        <div className="flex items-center gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={() => navigate(`/team/${team.id}/settings`)}
          >
            <Settings className="h-4 w-4 mr-1.5" />
            Settings
          </Button>
          <Button size="sm" asChild>
            <Link to="/scan">
              <ScanLine className="h-4 w-4 mr-1.5" />
              New Scan
            </Link>
          </Button>
        </div>
      </div>

      {/* KPIs */}
      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        <KpiCard
          title="Total Scans"
          value={stats.totalScans}
          icon={ScanLine}
          iconColor="text-primary"
          iconBg="bg-primary/8"
        />
        <KpiCard
          title="Avg Score"
          value={stats.avgScore}
          suffix="/100"
          icon={Target}
          iconColor={cn(
            stats.avgScore >= 70
              ? "text-emerald-500"
              : stats.avgScore >= 40
              ? "text-amber-500"
              : "text-red-500"
          )}
          iconBg={cn(
            stats.avgScore >= 70
              ? "bg-emerald-50"
              : stats.avgScore >= 40
              ? "bg-amber-50"
              : "bg-red-50"
          )}
          valueColor={getScoreColor(stats.avgScore)}
        />
        <KpiCard
          title="Members"
          value={stats.memberCount}
          icon={Users}
          iconColor="text-blue-500"
          iconBg="bg-blue-50"
        />
        <KpiCard
          title="Critical Issues"
          value={stats.criticalIssues}
          icon={AlertTriangle}
          iconColor="text-red-500"
          iconBg="bg-red-50"
        />
      </div>

      {/* Recent team scans */}
      <Card className="border-border/40">
        <CardHeader className="pb-0">
          <CardTitle className="text-base font-semibold">Recent Scans</CardTitle>
        </CardHeader>
        <CardContent className="p-0 mt-4">
          {scansLoading ? (
            <div className="space-y-2 p-4">
              {Array.from({ length: 5 }).map((_, i) => (
                <Skeleton key={i} className="h-12 w-full" />
              ))}
            </div>
          ) : scansError ? (
            <ErrorState
              title="Failed to load scans"
              description="Could not fetch team scans."
              onRetry={refetchScans}
              className="py-12"
            />
          ) : scans.length === 0 ? (
            <EmptyState
              icon={Globe}
              title="No scans yet"
              description="Run your first scan for this team workspace."
              actionLabel="New Scan"
              actionHref="/scan"
              className="py-12"
            />
          ) : (
            <Table>
              <TableHeader>
                <TableRow className="hover:bg-transparent">
                  <TableHead>URL</TableHead>
                  <TableHead>Score</TableHead>
                  <TableHead className="hidden sm:table-cell">Status</TableHead>
                  <TableHead className="hidden md:table-cell">Date</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {scans.slice(0, 20).map((scan) => (
                  <TableRow
                    key={scan.id}
                    className="cursor-pointer hover:bg-muted/30"
                    onClick={() => navigate(`/reports/${scan.id}`)}
                  >
                    <TableCell className="max-w-[200px]">
                      <span className="text-sm truncate block">
                        {scan.url.replace(/^https?:\/\//, "")}
                      </span>
                    </TableCell>
                    <TableCell>
                      {scan.overall_score !== null ? (
                        <span
                          className={cn(
                            "text-sm font-semibold tabular-nums",
                            getScoreColor(scan.overall_score)
                          )}
                        >
                          {scan.overall_score}
                        </span>
                      ) : (
                        <span className="text-sm text-muted-foreground">—</span>
                      )}
                    </TableCell>
                    <TableCell className="hidden sm:table-cell">
                      <StatusBadge status={scan.status} />
                    </TableCell>
                    <TableCell className="hidden md:table-cell text-sm text-muted-foreground">
                      {formatRelativeDate(scan.created_at)}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </PageTransition>
  );

  if (!canAccess) {
    return (
      <PremiumLock message="Team workspaces are available on Pro and Agency plans">
        {content}
      </PremiumLock>
    );
  }

  return content;
}

import { useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import {
  AlertTriangle,
  ArrowLeft,
  Loader2,
  Palette,
  Trash2,
  UserPlus,
  Users,
} from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";
import { Separator } from "@/components/ui/separator";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { PageTransition } from "@/components/shared/PageTransition";
import { ErrorState } from "@/components/shared/ErrorState";
import { EmptyState } from "@/components/shared/EmptyState";
import { MemberList } from "@/components/team/MemberList";
import { InviteMemberDialog } from "@/components/team/InviteMemberDialog";
import { useAuth } from "@/contexts/AuthContext";
import {
  useTeam,
  useTeamMembers,
  useUpdateTeam,
  useDeleteTeam,
} from "@/hooks/use-teams";
import { isAgencyPlan } from "@/types/index";

// ── Loading skeleton ──────────────────────────────────────────────

function SettingsSkeleton() {
  return (
    <div className="space-y-6 p-6">
      <Skeleton className="h-8 w-48" />
      <div className="grid gap-4">
        {Array.from({ length: 3 }).map((_, i) => (
          <Skeleton key={i} className="h-32" />
        ))}
      </div>
    </div>
  );
}

// ── General tab ───────────────────────────────────────────────────

function GeneralTab({
  teamId,
  teamName,
  ownerId,
}: {
  teamId: string;
  teamName: string;
  ownerId: string;
}) {
  const [name, setName] = useState(teamName);
  const updateTeam = useUpdateTeam(teamId);
  const deleteTeam = useDeleteTeam();
  const { user, activeTeamId, switchTeam } = useAuth();
  const navigate = useNavigate();

  const isOwner = user?.id === ownerId;
  const hasChanges = name.trim() !== teamName;

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!hasChanges || !name.trim()) return;
    updateTeam.mutate({ name: name.trim() });
  };

  const handleDelete = async () => {
    await deleteTeam.mutateAsync(teamId);
    if (activeTeamId === teamId) switchTeam(null);
    navigate("/dashboard");
  };

  return (
    <div className="space-y-6">
      <Card className="border-border/40">
        <CardHeader>
          <CardTitle className="text-sm font-semibold">Team Name</CardTitle>
          <CardDescription className="text-xs">
            This is the display name for your team workspace.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSave} className="flex gap-3 max-w-sm">
            <Input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Team name"
              maxLength={80}
              disabled={!isOwner}
            />
            {isOwner && (
              <Button
                type="submit"
                size="sm"
                disabled={!hasChanges || updateTeam.isPending}
              >
                {updateTeam.isPending && (
                  <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                )}
                Save
              </Button>
            )}
          </form>
        </CardContent>
      </Card>

      {isOwner && (
        <Card className="border-red-200/60 bg-red-50/20">
          <CardHeader>
            <CardTitle className="text-sm font-semibold text-destructive flex items-center gap-2">
              <AlertTriangle className="h-4 w-4" />
              Danger Zone
            </CardTitle>
            <CardDescription className="text-xs">
              Deleting a team is permanent and cannot be undone. All team scans will be
              disassociated.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <AlertDialog>
              <AlertDialogTrigger asChild>
                <Button variant="destructive" size="sm">
                  <Trash2 className="h-4 w-4 mr-2" />
                  Delete Team
                </Button>
              </AlertDialogTrigger>
              <AlertDialogContent>
                <AlertDialogHeader>
                  <AlertDialogTitle>Delete this team?</AlertDialogTitle>
                  <AlertDialogDescription>
                    This will permanently delete <strong>{teamName}</strong> and remove all
                    members. This action cannot be undone.
                  </AlertDialogDescription>
                </AlertDialogHeader>
                <AlertDialogFooter>
                  <AlertDialogCancel>Cancel</AlertDialogCancel>
                  <AlertDialogAction
                    onClick={handleDelete}
                    className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                  >
                    {deleteTeam.isPending && (
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    )}
                    Delete Team
                  </AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>
            </AlertDialog>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

// ── Members tab ───────────────────────────────────────────────────

function MembersTab({
  teamId,
  ownerId,
}: {
  teamId: string;
  ownerId: string;
}) {
  const [inviteOpen, setInviteOpen] = useState(false);
  const { data: members = [], isLoading } = useTeamMembers(teamId);
  const { user } = useAuth();

  const isOwner = user?.id === ownerId;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <p className="text-sm text-muted-foreground">
          {members.length} {members.length === 1 ? "member" : "members"}
        </p>
        {isOwner && (
          <Button size="sm" onClick={() => setInviteOpen(true)}>
            <UserPlus className="h-4 w-4 mr-1.5" />
            Invite Member
          </Button>
        )}
      </div>

      <Card className="border-border/40">
        <CardContent className="p-0">
          {isLoading ? (
            <div className="space-y-2 p-4">
              {Array.from({ length: 4 }).map((_, i) => (
                <Skeleton key={i} className="h-12" />
              ))}
            </div>
          ) : members.length === 0 ? (
            <EmptyState
              icon={Users}
              title="No members yet"
              description="Invite teammates to collaborate on this workspace."
              actionLabel="Invite Member"
              onAction={() => setInviteOpen(true)}
              className="py-10"
            />
          ) : (
            <MemberList teamId={teamId} members={members} ownerId={ownerId} />
          )}
        </CardContent>
      </Card>

      <InviteMemberDialog
        open={inviteOpen}
        onOpenChange={setInviteOpen}
        teamId={teamId}
      />
    </div>
  );
}

// ── Branding tab ──────────────────────────────────────────────────

function BrandingTab({
  teamId,
  team,
}: {
  teamId: string;
  team: { brand_color: string; custom_domain: string | null; logo_url: string | null };
}) {
  const { profile } = useAuth();
  const [color, setColor] = useState(team.brand_color ?? "#5B5FC7");
  const [domain, setDomain] = useState(team.custom_domain ?? "");
  const updateTeam = useUpdateTeam(teamId);

  const isAgency = profile ? isAgencyPlan(profile.plan) : false;

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    updateTeam.mutate({
      brand_color: color,
      custom_domain: domain.trim() || null,
    });
  };

  return (
    <form onSubmit={handleSave} className="space-y-6">
      <Card className="border-border/40">
        <CardHeader>
          <CardTitle className="text-sm font-semibold">Brand Color</CardTitle>
          <CardDescription className="text-xs">
            Used for team workspace accents.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-3">
            <input
              type="color"
              value={color}
              onChange={(e) => setColor(e.target.value)}
              className="h-9 w-14 cursor-pointer rounded-md border border-border/60 bg-transparent p-0.5"
              aria-label="Brand color"
            />
            <Input
              value={color}
              onChange={(e) => setColor(e.target.value)}
              className="w-28 font-mono text-sm"
              placeholder="#5B5FC7"
              maxLength={7}
            />
          </div>
        </CardContent>
      </Card>

      <Card className={!isAgency ? "border-border/30 opacity-60" : "border-border/40"}>
        <CardHeader>
          <CardTitle className="text-sm font-semibold flex items-center gap-2">
            Custom Domain
            {!isAgency && (
              <span className="text-xs bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded">
                Agency plan
              </span>
            )}
          </CardTitle>
          <CardDescription className="text-xs">
            Serve white-label reports from your own domain.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Input
            value={domain}
            onChange={(e) => setDomain(e.target.value)}
            placeholder="reports.yourdomain.com"
            disabled={!isAgency}
            className="max-w-sm"
          />
        </CardContent>
      </Card>

      <Separator />

      <Button type="submit" size="sm" disabled={updateTeam.isPending}>
        {updateTeam.isPending && (
          <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
        )}
        Save Branding
      </Button>
    </form>
  );
}

// ── Page ─────────────────────────────────────────────────────────

export default function TeamSettings() {
  const { id: teamId } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();

  const {
    data: team,
    isLoading,
    isError,
    refetch,
  } = useTeam(teamId);

  if (isLoading) return <SettingsSkeleton />;

  if (isError || !team) {
    return (
      <ErrorState
        title="Team not found"
        description="This team doesn't exist or you don't have access."
        onRetry={refetch}
        className="p-12"
      />
    );
  }

  const isOwnerOrAdmin =
    user?.id === team.owner_id;

  if (!isOwnerOrAdmin) {
    return (
      <div className="p-6">
        <p className="text-sm text-muted-foreground">
          You don't have permission to manage this team's settings.
        </p>
      </div>
    );
  }

  return (
    <PageTransition className="space-y-6 p-6 max-w-3xl">
      {/* Header */}
      <div className="space-y-1">
        <Button
          variant="ghost"
          size="sm"
          className="mb-2 -ml-2 text-muted-foreground"
          onClick={() => navigate(`/team/${team.id}`)}
        >
          <ArrowLeft className="h-4 w-4 mr-1.5" />
          Back to Dashboard
        </Button>
        <h1 className="text-xl font-bold tracking-tight">{team.name} — Settings</h1>
        <p className="text-sm text-muted-foreground">
          Manage members, branding, and team configuration.
        </p>
      </div>

      <Tabs defaultValue="general">
        <TabsList className="mb-6">
          <TabsTrigger value="general">General</TabsTrigger>
          <TabsTrigger value="members">
            <Users className="h-3.5 w-3.5 mr-1.5" />
            Members
          </TabsTrigger>
          <TabsTrigger value="branding">
            <Palette className="h-3.5 w-3.5 mr-1.5" />
            Branding
          </TabsTrigger>
        </TabsList>

        <TabsContent value="general">
          <GeneralTab teamId={team.id} teamName={team.name} ownerId={team.owner_id} />
        </TabsContent>

        <TabsContent value="members">
          <MembersTab teamId={team.id} ownerId={team.owner_id} />
        </TabsContent>

        <TabsContent value="branding">
          <BrandingTab
            teamId={team.id}
            team={{
              brand_color: team.brand_color ?? "#5B5FC7",
              custom_domain: team.custom_domain,
              logo_url: team.logo_url,
            }}
          />
        </TabsContent>
      </Tabs>
    </PageTransition>
  );
}

import { useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { Loader2, CheckCircle, AlertCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useAuth } from "@/contexts/AuthContext";
import { useAcceptInvite } from "@/hooks/use-teams";

export default function AcceptInvite() {
  const { token } = useParams<{ token: string }>();
  const navigate = useNavigate();
  const { user, loading: authLoading, switchTeam } = useAuth();
  const acceptInvite = useAcceptInvite();

  useEffect(() => {
    // Wait until auth is resolved and token is present
    if (authLoading || !token) return;

    // Not logged in — redirect to login with return path
    if (!user) {
      navigate(`/login?redirect=/invite/${token}`);
      return;
    }

    acceptInvite.mutate(token, {
      onSuccess: (data) => {
        switchTeam(data.team_id);
        navigate(`/team/${data.team_id}`);
      },
    });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authLoading, user, token]);

  if (authLoading || acceptInvite.isPending) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <Card className="w-full max-w-sm text-center">
          <CardHeader>
            <Loader2 className="mx-auto h-8 w-8 animate-spin text-primary" />
            <CardTitle className="text-base mt-3">Accepting invitation…</CardTitle>
          </CardHeader>
        </Card>
      </div>
    );
  }

  if (acceptInvite.isSuccess) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <Card className="w-full max-w-sm text-center">
          <CardContent className="pt-8 pb-6 flex flex-col items-center gap-3">
            <CheckCircle className="h-10 w-10 text-emerald-500" />
            <p className="font-semibold">You have joined the team!</p>
            <Button size="sm" onClick={() => navigate("/dashboard")}>
              Go to Dashboard
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (acceptInvite.isError) {
    const msg =
      acceptInvite.error instanceof Error
        ? acceptInvite.error.message
        : "The invitation may have expired or already been used.";

    return (
      <div className="flex min-h-screen items-center justify-center px-4">
        <Card className="w-full max-w-sm text-center">
          <CardContent className="pt-8 pb-6 flex flex-col items-center gap-3">
            <AlertCircle className="h-10 w-10 text-red-500" />
            <p className="font-semibold text-foreground">Invitation invalid</p>
            <p className="text-sm text-muted-foreground">{msg}</p>
            <Button size="sm" onClick={() => navigate("/dashboard")}>
              Go to Dashboard
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return null;
}

